// Pedidos de prueba o en modo desarrollo: no se mandan a Norva
if ($('Buscar overrides').first().json.modo_operacion === 'desarrollo' || $('Parsear mensaje').first().json.esPrueba === true) return [];
const item = $('Construir ticket').first().json;
const ps = $('Procesar salida').first().json;
const p = ps.pedido || {};
const id = item.id;
const esRetiro = item.esRetiro;

// Determinar metodo de pago compatible con Norva ERP (EFECTIVO, TARJETA, TRANSFERENCIA, POS_MOVIL)
let metodo = 'EFECTIVO';
const pagoStr = String(p.pago || '').toLowerCase();
if (pagoStr.includes('transf')) {
  metodo = 'TRANSFERENCIA';
} else if (pagoStr.includes('tarj') || pagoStr.includes('pos') || pagoStr.includes('deb') || pagoStr.includes('cred') || pagoStr.includes('qr')) {
  metodo = 'TARJETA';
}

// Observaciones completas (productos pedidos + notas + vuelto + factura)
let obs = [];
const itemsText = String(p.items || '').trim();
if (itemsText) {
  obs.push('🍽️ PRODUCTOS: ' + itemsText.replace(/\n+/g, ' | '));
}
if (p.notas && String(p.notas).trim() !== '-' && String(p.notas).trim() !== '') {
  obs.push('📝 Notas: ' + p.notas);
}
if (p.vuelto && String(p.vuelto).trim() !== '-' && String(p.vuelto).trim() !== 'no') {
  obs.push('💵 Vuelto para: ' + p.vuelto);
}
if (p.factura && p.factura.ruc) {
  obs.push('🧾 FACTURA: RUC ' + p.factura.ruc + ' - ' + (p.factura.razon_social || ''));
}

const direccion = esRetiro ? 'RETIRO EN LOCAL - Benjis Lambaré' : (p.ubicacion || 'Sin dirección');

const norvaPayload = {
  origen_tipo: 'WHATSAPP',
  origen_externo_id: 'BENJIS-' + id,
  cliente: {
    nombre: ps.name || 'Cliente WhatsApp',
    telefono: ps.phone || '',
    direccion: direccion,
    referencia: itemsText ? ('Productos: ' + itemsText.replace(/\n+/g, ' | ')) : undefined,
    ruc_o_cedula: (p.factura && p.factura.ruc) ? String(p.factura.ruc) : undefined
  },
  items: [
    {
      item_id: 12,
      sku: 'WHATSAPP',
      cantidad: 1,
      precio_unitario: Number(p.subtotal || 0),
      notas: itemsText || 'Pedido WhatsApp'
    }
  ],
  costo_envio: esRetiro ? 0 : Number(p.envio || 0),
  metodo_pago: metodo,
  observaciones: obs.join(' || ') || 'Pedido WhatsApp Benjis',
  auto_confirmar: true
};

return [{ json: { norvaPayload, ...item } }];

