// Lee el comprobante que extrajo la visión y decide si es válido (por código, no por la IA)
const vis = $('Analizar imagen (Vision)').first().json || {};
const t = String((vis.choices && vis.choices[0] && vis.choices[0].message && vis.choices[0].message.content) || '');
const esComp = /TIPO:\s*COMPROBANTE/i.test(t);
const linea = (k) => { const m = t.match(new RegExp(k + '\\s*:\\s*([^\\n;]*)', 'i')); return m ? m[1].replace(/\*/g, '').trim() : ''; };
const destinatario = linea('DESTINATARIO'), cuenta = linea('CUENTA_DESTINO'), origen = linea('ORIGEN');
const monto = Number(linea('MONTO_GS').replace(/[^0-9]/g, '')) || 0;
const fechaTxt = linea('FECHA');
const nro = linea('NRO').replace(/[^A-Za-z0-9-]/g, '');
const destinoOk = /(manhattan|80152605|6192944219)/i.test(destinatario + ' ' + cuenta);
let fechaOk = true, fechaIso = '';
const mf = fechaTxt.match(/(\d{1,2})\/(\d{1,2})\/(\d{4})/);
if (mf) {
  fechaIso = mf[3] + '-' + mf[2].padStart(2, '0') + '-' + mf[1].padStart(2, '0');
  const hoy = new Date(new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Asuncion' }).format(new Date()) + 'T12:00:00Z');
  fechaOk = Math.abs((hoy - new Date(fechaIso + 'T12:00:00Z')) / 86400000) <= 1;
}
let motivo = '';
if (esComp) {
  if (!destinoOk) motivo = 'no está a nombre de MANHATTAN FOOD GROUP E.A.S. (figura: ' + (destinatario && destinatario !== '?' ? destinatario : (cuenta || 'no se ve el destinatario')) + ')';
  else if (!fechaOk) motivo = 'la fecha del comprobante (' + fechaTxt + ') no es de hoy';
  else if (!monto) motivo = 'no se puede leer el monto';
}
return [{ json: { esComp, destinatario, cuenta, origen, monto, fecha: fechaIso, nro, destinoOk, fechaOk, motivo, texto: t } }];

