  SELECT $1, $2::jsonb, now() WHERE $3 = 'guardar'
  ON CONFLICT (telefono) DO UPDATE SET pedido = EXCLUDED.pedido, creado_at = now()
  RETURNING 1
), b AS (
  DELETE FROM benjis_pedido_pendiente WHERE $3 = 'borrar' AND telefono = $1 RETURNING 1
), e AS (
  UPDATE carritos_pendientes SET recordatorio_enviado = true, fecha_recordatorio = now() WHERE $3 = 'escalado' AND telefono = $1 RETURNING 1
)
SELECT (SELECT count(*) FROM g) AS guardado, (SELECT count(*) FROM b) AS borrado, (SELECT count(*) FROM e) AS recordatorio_frenado;

