sd.alertas[clave] = { t: ahora, omitidas: 0 };

const hora = new Date().toLocaleString('es-PY', { timeZone: 'America/Asuncion', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false });
